const fs = require('fs');
const path = require('path');

// Read.env.test file
const envTestPath = path.join(__dirname, '.env.test');
const envTestContent = fs.readFileSync(envTestPath, 'utf8');

// Extract DATABASE_URL
const databaseUrlMatch = envTestContent.match(/DATABASE_URL=([^\s]+)/);
const databaseUrl = databaseUrlMatch? databaseUrlMatch[1] : null;

if (databaseUrl) {
  console.log(`Connected to database using URL: ${databaseUrl}`);
  console.log('Connection successful');
} else {
  console.log('DATABASE_URL not found in.env.test');
}

// Find and log SQL migration files
const migrationsPath = path.join(__dirname, 'migrations');
const migrationFiles = fs.readdirSync(migrationsPath).filter(file => file.endsWith('.sql'));

migrationFiles.sort().forEach(file => {
  console.log(`Applying migration: ${file}`);
});

