const fs = require('fs');
const path = require('path');

const migrationDir = path.join(__dirname, 'migrations');
const envFilePath = path.join(__dirname, '.env.test');

// Read the.env.test file to get the DATABASE_URL
fs.readFile(envFilePath, 'utf8', (err, data) => {
  if (err) {
    console.error('Error reading.env.test file:', err);
    return;
  }

  // Extract the DATABASE_URL from the.env.test file
  const databaseUrlMatch = data.match(/DATABASE_URL=([^\n]+)/);
  if (!databaseUrlMatch) {
    console.error('DATABASE_URL not found in.env.test file');
    return;
  }

  const databaseUrl = databaseUrlMatch[1];
  console.log(`Connected to database using URL: ${databaseUrl}`);

  // Read all SQL files in the migrations directory
fs.readdir(migrationDir, (err, files) => {
    if (err) {
      console.error('Error reading migrations directory:', err);
      return;
    }

    // Filter and sort SQL files
    const sqlFiles = files
    .filter(file => path.extname(file) === '.sql')
    .sort();

    // Log each SQL file
    sqlFiles.forEach(file => {
      console.log(`Applying migration: ${file}`);
    });
  });
});

