const path = require('path');
const dotenv = require('dotenv');
const axios = require('axios');

dotenv.config({ path: '.env.test' });

const databaseUrl = process.env.DATABASE_URL;
if (databaseUrl) {
  console.log(`Connected to database using URL: ${databaseUrl}`);
} else {
  console.error('DATABASE_URL not found in.env.test');
}

axios.post('http://localhost:47301/api/audit', {
  DATABASE_URL: databaseUrl,
  AWS_ACCESS_KEY_ID: process.env.AWS_ACCESS_KEY_ID,
  AWS_SECRET_ACCESS_KEY: process.env.AWS_SECRET_ACCESS_KEY,
  ANTHROPIC_API_KEY: process.env.ANTHROPIC_API_KEY,
  STRIPE_SECRET_KEY: process.env.STRIPE_SECRET_KEY,
  LOGFIRE_TOKEN: process.env.LOGFIRE_TOKEN
}).then(response => {
  console.log('Audit log successful:', response.data);
}).catch(error => {
  console.error('Audit log failed:', error);
});

